export type ProductRow = {
  id: number;
  title: string;
  category: string;
  price: number;
  stock: number;
  rating: number;
};

export type ProductQuery = {
  q: string;
  sortBy: string;
  order: "asc" | "desc";
  page: number;
};

export type ProductPage = { products: ProductRow[]; total: number; skip: number; limit: number };

export function productsPath({ q, sortBy, order, page }: ProductQuery) {
  const p = new URLSearchParams({
    limit: String(PAGE_SIZE),
    skip: String((page - 1) * PAGE_SIZE),
    select: "title,category,price,stock,rating",
  });
  if (q) p.set("q", q);
  if (sortBy) {
    p.set("sortBy", sortBy);
    p.set("order", order);
  }
  // pencarian punya endpoint sendiri, tapi limit/skip/sortBy tetap berlaku
  return `/products${q ? "/search" : ""}?${p}`;
}

export function getProducts(query: ProductQuery, signal?: AbortSignal) {
  return getJson<ProductPage>(productsPath(query), signal);
}

import { useSearchParams } from "react-router";

// Membaca dan mengubah query string. Nilai kosong dihapus dari URL.
export function useUrlParams() {
  const [params, setParams] = useSearchParams();

  function update(changes: Record<string, string>) {
    const next = new URLSearchParams(params);
    for (const [key, value] of Object.entries(changes)) {
      if (value) next.set(key, value);
      else next.delete(key);
    }
    setParams(next);
  }

  return [params, update] as const;
}

export function pageFrom(params: URLSearchParams) {
  return Math.max(1, Math.floor(Number(params.get("page"))) || 1);
}

export function Loading() {
  return <p role="status">Memuat data...</p>;
}

export function ErrorBox({ error, onRetry }: { error: Error; onRetry: () => void }) {
  return (
    <div role="alert" className="error">
      <p>Gagal memuat: {error.message}</p>
      <button type="button" onClick={onRetry}>Coba lagi</button>
    </div>
  );
}

type Props = {
  page: number;
  total: number;
  pageSize: number;
  onChange: (page: number) => void;
};

export function Pagination({ page, total, pageSize, onChange }: Props) {
  const last = Math.max(1, Math.ceil(total / pageSize));
  return (
    <nav className="pager" aria-label="Halaman">
      <button type="button" onClick={() => onChange(page - 1)} disabled={page <= 1}>
        Sebelumnya
      </button>
      <span>Halaman {page} dari {last}</span>
      <button type="button" onClick={() => onChange(page + 1)} disabled={page >= last}>
        Berikutnya
      </button>
    </nav>
  );
}

import { Link } from "react-router";
import { keepPreviousData, useQuery } from "@tanstack/react-query";
import { getProducts, PAGE_SIZE, usd, type ProductQuery } from "../api";
import { pageFrom, useUrlParams } from "../useUrlParams";
import { ErrorBox, Loading } from "../components/Status";
import { Pagination } from "../components/Pagination";

const COLUMNS = [
  ["title", "Nama"],
  ["category", "Kategori"],
  ["price", "Harga"],
  ["stock", "Stok"],
  ["rating", "Rating"],
] as const;

export function Produk() {
  const [params, update] = useUrlParams();
  const query: ProductQuery = {
    q: params.get("q") ?? "",
    sortBy: params.get("sort") ?? "",
    order: params.get("order") === "desc" ? "desc" : "asc",
    page: pageFrom(params),
  };

  const { data, isPending, isError, error, refetch, isFetching } = useQuery({
    queryKey: ["products", query],
    queryFn: ({ signal }) => getProducts(query, signal),
    placeholderData: keepPreviousData,
  });

  function sortBy(column: string) {
    const order = query.sortBy === column && query.order === "asc" ? "desc" : "asc";
    update({ sort: column, order, page: "" });
  }

  return (
    <section>
      <h1>Produk</h1>

      {/* key: form dibuat ulang saat q di URL berubah, misalnya karena tombol Back */}
      <form
        key={query.q}
        className="toolbar"
        role="search"
        onSubmit={(e) => {
          e.preventDefault();
          const q = String(new FormData(e.currentTarget).get("q") ?? "").trim();
          update({ q, page: "" });
        }}
      >
        <input name="q" type="search" aria-label="Cari produk" placeholder="Cari produk..." defaultValue={query.q} />
        <button type="submit">Cari</button>
        {isFetching && !isPending && <span role="status">Memperbarui...</span>}
      </form>

      {isPending ? (
        <Loading />
      ) : isError ? (
        <ErrorBox error={error} onRetry={() => refetch()} />
      ) : (
        <>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  {COLUMNS.map(([key, label]) => {
                    const active = query.sortBy === key;
                    return (
                      <th key={key} aria-sort={active ? (query.order === "asc" ? "ascending" : "descending") : "none"}>
                        <button type="button" onClick={() => sortBy(key)}>
                          {label}
                          {active && (query.order === "asc" ? " ▲" : " ▼")}
                        </button>
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {data.products.map((p) => (
                  <tr key={p.id}>
                    <td><Link to={`/produk/${p.id}`}>{p.title}</Link></td>
                    <td>{p.category}</td>
                    <td>{usd.format(p.price)}</td>
                    <td>{p.stock}</td>
                    <td>{p.rating.toFixed(1)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {data.products.length === 0 && <p>Tidak ada produk yang cocok{query.q && ` dengan "${query.q}"`}.</p>}
          <Pagination
            page={query.page}
            total={data.total}
            pageSize={PAGE_SIZE}
            onChange={(page) => update({ page: String(page) })}
          />
        </>
      )}
    </section>
  );
}

