export type Product = ProductRow & {
  description: string;
  brand?: string; // produk kategori groceries tidak punya brand
  thumbnail: string;
  reviews: { rating: number; comment: string; reviewerName: string }[];
};

export function getProduct(id: string, signal?: AbortSignal) {
  return getJson<Product>(`/products/${encodeURIComponent(id)}`, signal);
}

export type User = {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  age: number;
  company: { title: string };
};

export type UserPage = { users: User[]; total: number; skip: number; limit: number };

export function getUsers({ q, page }: { q: string; page: number }, signal?: AbortSignal) {
  const p = new URLSearchParams({
    limit: String(PAGE_SIZE),
    skip: String((page - 1) * PAGE_SIZE),
    select: "firstName,lastName,email,age,company",
  });
  if (q) p.set("q", q);
  return getJson<UserPage>(`/users${q ? "/search" : ""}?${p}`, signal);
}

import { Link, useParams } from "react-router";
import { useQuery } from "@tanstack/react-query";
import { getProduct, usd } from "../api";
import { ErrorBox, Loading } from "../components/Status";

export function ProdukDetail() {
  const { id = "" } = useParams();
  const { data, isPending, isError, error, refetch } = useQuery({
    queryKey: ["product", id],
    queryFn: ({ signal }) => getProduct(id, signal),
  });

  if (isPending) return <Loading />;
  if (isError) return <ErrorBox error={error} onRetry={() => refetch()} />;

  return (
    <article>
      <p><Link to="/produk">&larr; Semua produk</Link></p>
      <div className="detail">
        <img src={data.thumbnail} alt={data.title} />
        <div>
          <h1>{data.title}</h1>
          <p>{data.brand ?? "Tanpa merek"} &middot; {data.category}</p>
          <p><strong>{usd.format(data.price)}</strong> &middot; stok {data.stock} &middot; rating {data.rating.toFixed(1)}</p>
          <p>{data.description}</p>
          <h2>Ulasan ({data.reviews.length})</h2>
          <ul>
            {data.reviews.map((r, i) => (
              <li key={i}>
                <strong>{r.reviewerName}</strong> ({r.rating}/5): {r.comment}
              </li>
            ))}
          </ul>
        </div>
