export async function getSummary(signal?: AbortSignal) {
  // limit=0 berarti "ambil semua"; select membuat responsnya tetap kecil
  const [products, users, carts] = await Promise.all([
    getJson<{ products: { category: string }[]; total: number }>("/products?limit=0&select=category", signal),
    getJson<{ total: number }>("/users?limit=1&select=id", signal),
    getJson<{ carts: { total: number }[]; total: number }>("/carts?limit=0&select=total", signal),
  ]);

  const counts = new Map<string, number>();
  for (const p of products.products) counts.set(p.category, (counts.get(p.category) ?? 0) + 1);

  return {
    products: products.total,
    users: users.total,
    carts: carts.total,
    revenue: carts.carts.reduce((sum, c) => sum + c.total, 0),
    categories: [...counts]
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count),
  };
}

import { useQuery } from "@tanstack/react-query";
import { Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { getSummary, usd } from "../api";
import { ErrorBox, Loading } from "../components/Status";

export function Ringkasan() {
  const { data, isPending, isError, error, refetch } = useQuery({
    queryKey: ["summary"],
    queryFn: ({ signal }) => getSummary(signal),
  });

  if (isPending) return <Loading />;
  if (isError) return <ErrorBox error={error} onRetry={() => refetch()} />;

  const stats = [
    ["Produk", data.products.toLocaleString("id-ID")],
    ["Pengguna", data.users.toLocaleString("id-ID")],
    ["Keranjang", data.carts.toLocaleString("id-ID")],
    ["Nilai keranjang", usd.format(data.revenue)],
  ];

  return (
    <section>
      <h1>Ringkasan</h1>
      <div className="cards">
        {stats.map(([label, value]) => (
          <div className="card" key={label}>
            <span>{label}</span>
            <strong>{value}</strong>
          </div>
        ))}
      </div>

      <div className="card">
        <h2>Jumlah produk per kategori</h2>
        <ResponsiveContainer width="100%" height={data.categories.length * 26 + 40}>
          <BarChart data={data.categories} layout="vertical" margin={{ left: 8, right: 16 }}>
            <XAxis type="number" allowDecimals={false} />
            <YAxis type="category" dataKey="name" width={150} tick={{ fontSize: 12 }} />
            <Tooltip />
            <Bar dataKey="count" name="Produk" fill="#4a7c59" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}

