import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { createMemoryRouter, RouterProvider } from "react-router";
import { afterEach, expect, test, vi } from "vitest";
import { Produk } from "./Produk";

const page = {
  products: [{ id: 1, title: "Kopi Susu", category: "groceries", price: 2.5, stock: 10, rating: 4.5 }],
  total: 25,
  skip: 0,
  limit: 10,
};

function renderAt(url: string) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  const router = createMemoryRouter(
    [
      { path: "/produk", element: <Produk /> },
      { path: "/produk/:id", element: <p>detail</p> },
    ],
    { initialEntries: [url] },
  );
  render(
    <QueryClientProvider client={client}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  );
  return router;
}

afterEach(() => vi.unstubAllGlobals());

test("filter di URL diteruskan ke API", async () => {
  // Response dibuat baru di tiap panggilan, karena body hanya bisa dibaca sekali
  const fetchMock = vi.fn(async (_url: string) => Response.json(page));
  vi.stubGlobal("fetch", fetchMock);

  renderAt("/produk?q=kopi&sort=price&order=desc&page=2");

  expect(await screen.findByText("Kopi Susu")).toBeInTheDocument();
  expect(screen.getByRole("searchbox")).toHaveValue("kopi");

  const url = new URL(fetchMock.mock.calls[0][0]);
  expect(url.pathname).toBe("/products/search");
  expect(url.searchParams.get("q")).toBe("kopi");
  expect(url.searchParams.get("skip")).toBe("10");
  expect(url.searchParams.get("sortBy")).toBe("price");
  expect(url.searchParams.get("order")).toBe("desc");
});

test("klik judul kolom menulis urutan ke URL", async () => {
  vi.stubGlobal("fetch", vi.fn(async (_url: string) => Response.json(page)));
  const router = renderAt("/produk");

  await userEvent.click(await screen.findByRole("button", { name: "Harga" }));
  await waitFor(() => expect(router.state.location.search).toBe("?sort=price&order=asc"));

  await userEvent.click(await screen.findByRole("button", { name: /Harga/ }));
  await waitFor(() => expect(router.state.location.search).toBe("?sort=price&order=desc"));
});

test("pesan error dari server ditampilkan", async () => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (_url: string) => Response.json({ message: "Server sedang sibuk" }, { status: 500 })),
  );
  renderAt("/produk");

  expect(await screen.findByRole("alert")).toHaveTextContent("Server sedang sibuk");
});

